import{_ as i,o as t,c as a,a2 as e}from"./chunks/framework.BYgiQ6KE.js";const n="/angular-tutorial-site/assets/EP.02-template-sugar.CZ-74IqB.svg",g=JSON.parse('{"title":"EP.02 模板里那些糖","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.02-template-sugar.md","filePath":"comics/EP.02-template-sugar.md","lastUpdated":1793863170000}'),l={name:"comics/EP.02-template-sugar.md"};function o(d,s,h,p,r,c){return t(),a("div",null,[...s[0]||(s[0]=[e('<h1 id="ep-02-模板里那些糖" tabindex="-1">EP.02 模板里那些糖 <a class="header-anchor" href="#ep-02-模板里那些糖" aria-label="Permalink to &quot;EP.02 模板里那些糖&quot;">​</a></h1><p><img src="'+n+`" alt="EP.02 模板里那些糖"></p><blockquote><p>对应正文：<a href="./../guide/part1/02-template-syntax">02-template-syntax</a>（1 模板语法与组件通信的三个支点 / 2 动手步骤 / 3 可运行示例 / 4 代码拆解 / 5 常见坑 / 7 自测）· 示例：<code>examples/template-syntax</code> · Playground id：<code>template-syntax</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君兴冲冲写 <code>@for (member of list()) { }</code>，编译器直接炸了——<strong>Angular 22 强制显式 <code>track</code></strong>，给每行一个稳定身份。</li><li><strong>第 2 格</strong>：码叔拆解编译器：<code>@if</code> / <code>@for</code> / <code>@switch</code> 不是指令，是<strong>模板 AST 节点</strong>，编译器直接生成结构指令——不需要在 <code>imports</code> 里声明 <code>NgIf</code> / <code>NgFor</code>。</li><li><strong>第 3 格</strong>：像素酱展示 <code>input()</code> / <code>input.required()</code> / <code>output()</code> 的组合拳：父组件 <code>[name]=&quot;member.name&quot;</code> 传输入，子组件 <code>(select)=&quot;onSelect($event)&quot;</code> 接输出，<code>$event</code> 就是 <code>emit</code> 的载荷。</li><li><strong>第 4 格</strong>：码叔结案——模板是<strong>声明式契约</strong>，编译器替你写指令，别用 <code>$index</code> 偷懒当 <code>track</code>。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-for-必须有-track" tabindex="-1">第 1 格 · @for 必须有 track <a class="header-anchor" href="#第-1-格-·-for-必须有-track" aria-label="Permalink to &quot;第 1 格 · @for 必须有 track&quot;">​</a></h3><p><code>track</code> 表达式告诉渲染器每一行的&quot;身份&quot;——列表增删或排序时，Angular 才能复用正确的 DOM 节点和组件实例：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- ✅ 数据自身稳定身份 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@for (member of visibleMembers(); track member.id) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">app-user-card</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> [name]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;member.name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} @empty {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;empty&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;没有符合条件的成员。&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>写 <code>track member.id</code> 等唯一字段，列表重排时不会造成卡片状态错位；</li><li>用 <code>track $index</code> 等于说&quot;第一行永远是第一行&quot;，删除中间一项后续状态全错；</li><li>空集合靠 <code>@empty { }</code> 兜底，不需要额外判空。</li></ul><h3 id="第-2-格-·-新控制流是编译期糖" tabindex="-1">第 2 格 · 新控制流是编译期糖 <a class="header-anchor" href="#第-2-格-·-新控制流是编译期糖" aria-label="Permalink to &quot;第 2 格 · 新控制流是编译期糖&quot;">​</a></h3><p><code>@if</code> / <code>@for</code> / <code>@switch</code> 与 <code>*ngIf</code> / <code>*ngFor</code> 本质上是同一套底层机制——前者是 Angular 17+ 起的<strong>模板 AST 扩展语法</strong>，编译器直接把它翻译成结构性指令：</p><table tabindex="0"><thead><tr><th>新语法</th><th>编译结果</th><th>需要导入</th></tr></thead><tbody><tr><td><code>@if (ok()) { }</code></td><td><code>*ngIf=&quot;ok()&quot;</code></td><td>❌ 不需要</td></tr><tr><td><code>@for (x of list(); track x.id) { }</code></td><td><code>*ngFor</code> + track</td><td>❌ 不需要</td></tr><tr><td><code>@switch (v) { @case (0) { } }</code></td><td><code>*ngSwitch</code> 全家桶</td><td>❌ 不需要</td></tr></tbody></table><p>混用新旧语法不会报错，但建议项目里统一用新控制流——代码更干净，也不会漏写 <code>imports</code>。</p><h3 id="第-3-格-·-input-output-通信" tabindex="-1">第 3 格 · input() / output() 通信 <a class="header-anchor" href="#第-3-格-·-input-output-通信" aria-label="Permalink to &quot;第 3 格 · input() / output() 通信&quot;">​</a></h3><p>Angular 17+ 把组件契约 signal 化了：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 子组件：声明输入输出</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">readonly name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> input.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 必填 signal</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">readonly role </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;未分配角色&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 可选 signal，带默认值</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">readonly select </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> output</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 事件发射器</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 子组件方法里这样发事件：this.select.emit(this.name());</span></span></code></pre></div><p>模板读取 signal 输入时<strong>必须加括号</strong> <code>{ { name() } }</code>，不是 <code>{ { name } }</code>（后者显示函数源码）。父组件用方括号传值 <code>[name]=&quot;member.name&quot;</code>，用圆括号接事件 <code>(select)=&quot;onSelect($event)&quot;</code>，<code>$event</code> 就是 <code>emit</code> 出来的载荷。</p><h3 id="第-4-格-·-组件通信还有一张牌-ng-content" tabindex="-1">第 4 格 · 组件通信还有一张牌：ng-content <a class="header-anchor" href="#第-4-格-·-组件通信还有一张牌-ng-content" aria-label="Permalink to &quot;第 4 格 · 组件通信还有一张牌：ng-content&quot;">​</a></h3><p><code>input()</code> 传数据值，<code>output()</code> 发事件，但父组件想传一段<strong>任意 HTML 片段</strong>怎么办？用 <code>&lt;ng-content /&gt;</code>：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 父组件 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">app-badge</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> [hot]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;score() &gt;= 90&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{{ score() }} 分&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">app-badge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 子组件模板里 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ng-content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 父组件写在标签之间的内容渲染到这里 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>投影内容属于<strong>父组件的模板上下文</strong>，里面的表达式访问父组件状态；子组件只决定位置和样式，不决定内容。适合卡片、弹窗、徽章这类布局型组件。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../guide/part1/02-template-syntax#5-常见坑">常见坑表格</a></p></blockquote><ol><li><code>@for</code> 漏写 <code>track</code> → <strong>Angular 22 强制显式声明</strong>，用数据自身的唯一 id，别偷懒写 <code>$index</code>；</li><li>删除中间项后卡片状态错位 → <strong><code>track $index</code> 让行身份随位置变化</strong>，改用稳定 id；</li><li>子组件显示函数源码 → <strong>signal 输入在模板里必须加括号</strong>，写 <code>name()</code> 而不是 <code>name</code>；</li><li><code>input.required</code> 漏传导致运行时报错 → <strong>补上绑定，或改为 <code>input(默认值)</code></strong>；</li><li>子组件标签内内容不显示 → <strong>子组件模板缺 <code>&lt;ng-content /&gt;</code></strong>，加占位槽。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><code>@for</code> 为什么必须有 <code>track</code>？——<strong>渲染器需要知道每一行的身份，列表增删排序时才能复用正确的 DOM 与组件实例；Angular 22 强制显式声明以避免隐式索引造成的状态错位</strong>。</li><li><code>input.required</code> 与 <code>input(&#39;未分配角色&#39;)</code> 的区别是什么？——<strong>两者都返回只读 signal。required 版本没有默认值，父组件漏传会在开发期报错；带默认值的版本可省略绑定，适合有合理兜底的配置项</strong>。</li><li><code>&lt;ng-content /&gt;</code> 和 <code>input()</code> 应该怎么选？——<strong><code>input()</code> 传一个数据值，属于子组件可感知的契约；<code>&lt;ng-content /&gt;</code> 接受任意 HTML 片段，投影内容仍属于父组件上下文。数据传值用 input，布局插槽用投影</strong>。</li></ol>`,27)])])}const E=i(l,[["render",o]]);export{g as __pageData,E as default};
